import random
try:
    with open("최고기록.txt") as 파일:
        최고 = int(파일.read())
except FileNotFoundError:
    최고 = 1000
답 = random.randint(1, 100)
번 = 0
while True:
    수 = int(input("맞혀 봐요: "))
    번 += 1
    if 수 == 답:
        print("정답!", 번, "번 만에 맞혔어요")
        break
    elif 수 < 답:
        print("더 큰 수예요")
    else:
        print("더 작은 수예요")
if 번 < 최고:
    with open("최고기록.txt", "w") as 파일:
        print(번, file=파일)
    print("새 기록이에요!")
else:
    print("최고 기록은", 최고, "번이에요")

